{
  "cases": [
    {
      "id": "C1",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Repeated testing is unreported; its occurrence cannot be inferred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "The tested system scored 70% in one reported run.",
          "reason": "One reported score does not establish consistency across runs."
        }
      ],
      "instrument_review": "EFPA 9.3 and 9.7 are reinterpreted as consistency across repeated AI evaluations under fixed conditions. Available stability evidence warrants 0 (insufficient information), not 1 (inadequate). Human retest-specific considerations do not directly apply."
    },
    {
      "id": "C2",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Contradicted",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "The passage explicitly rules out repeated testing."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "they ran the evaluation exactly once and did not repeat it",
          "reason": "Absent repeated observations, stability remains unknown; non-repetition does not demonstrate instability."
        }
      ],
      "instrument_review": "Under EFPA 9.3 and 9.7, reinterpreted for repeated AI evaluations, no stability estimate is available. This supports 0 for stability evidence, not a finding of inadequate score consistency."
    },
    {
      "id": "C3",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "Repeated evaluation with controlled conditions is explicitly reported."
        },
        {
          "id": "stable",
          "label": "Supported",
          "quote": "Scores ranged from 69% to 71%.",
          "reason": "The observed range meets the report's definition of stability: at most two percentage points."
        }
      ],
      "instrument_review": "EFPA 9.7 accommodates the observed range as alternative precision evidence, with 9.3 reinterpreted for AI reruns. Stability is supported for this system and setup under the stated definition. The range is not a reliability coefficient and does not justify a general precision rating."
    },
    {
      "id": "C4",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Supported",
          "quote": "They also repeated the evaluation ten times with the same system, inputs, instructions, resources, and settings.",
          "reason": "The developers explicitly conducted repeated evaluations under matching conditions."
        },
        {
          "id": "stable",
          "label": "Contradicted",
          "quote": "Scores ranged from 20% to 90%.",
          "reason": "The observed range exceeds the report's maximum two-percentage-point stability criterion."
        }
      ],
      "instrument_review": "EFPA 9.7 distinguishes conducting a precision study from obtaining acceptable results. Under the reported stability criterion, these results show inadequate consistency for this setup, unlike missing evidence. Section 9.8 requires attention to this variability when interpreting comparisons."
    },
    {
      "id": "C5",
      "probes": [
        {
          "id": "repeat_test",
          "label": "Not established",
          "quote": "The report does not say whether runs were repeated.",
          "reason": "Installation instructions do not establish that repeated evaluations occurred."
        },
        {
          "id": "stable",
          "label": "Not established",
          "quote": "They report no additional evaluation results.",
          "reason": "The added instructions supply no evidence of score consistency."
        }
      ],
      "instrument_review": "EFPA 6.3.8 concerns software instructions; sections 9.3 and 9.7 concern precision evidence. Documentation additions cannot substitute for repeated-run findings. Stability evidence remains 0 (insufficient information), without demonstrating poor consistency."
    },
    {
      "id": "C6",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "A achieved the higher observed score on the evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "The findings do not establish a cross-domain intelligence difference."
        }
      ],
      "instrument_review": "EFPA 3.2 and 10.1 support interpreting the observed scores within the tested content. Section 10.5 ties validity to intended use, which here is narrow comparison. Broader generalisation lacks evidence; repeatability is also unreported. Human intelligence interpretations are not assumed for AI systems."
    },
    {
      "id": "C7",
      "probes": [
        {
          "id": "narrow",
          "label": "Supported",
          "quote": "System A solves 80 puzzles and system B solves 60 in the reported evaluation.",
          "reason": "The observed results establish A's better performance on these evaluated puzzles."
        },
        {
          "id": "broad",
          "label": "Not established",
          "quote": "Only grid puzzles were tested; no findings about other tasks are supplied.",
          "reason": "A broad intended use does not supply evidence for cross-domain intelligence."
        }
      ],
      "instrument_review": "EFPA 6.1, 10.1, 10.3 and 10.5 require evidence supporting the stated construct and use. Grid-only findings leave validity for cross-domain selection insufficiently established. Under EFPA's critical-attribute guidance, this evidence gap prevents recommending that selection use beyond research or exceptional expert use; it does not prove A lacks greater general intelligence."
    },
    {
      "id": "C8",
      "probes": [
        {
          "id": "before",
          "label": "Not established",
          "quote": "Initially, only test scores were available.",
          "reason": "No initial evidence links the scores to improved workshop decisions."
        },
        {
          "id": "after",
          "label": "Supported",
          "quote": "With A, 90% of decisions were correct; with B, 70%.",
          "reason": "Random allocation, blinded correctness checking and a positive uncertainty interval support better correctness with A in the studied conditions."
        },
        {
          "id": "safety",
          "label": "Not established",
          "quote": "Time and safety outcomes were not measured.",
          "reason": "Correctness findings alone do not establish improved workplace safety."
        }
      ],
      "instrument_review": "EFPA 10.3.1.6 accommodates the randomised trial; 10.3.2 and 10.5 direct attention to relevant outcomes and intended use. The trial supports choosing assistance for correctness in this workshop, without establishing safety benefits or a test-score–outcome correlation. Human participants here provide outcome evidence rather than constituting the AI benchmark's test-taker population."
    }
  ],
  "closing_note": "No clarification was needed. The requested probe-level format permits relevant EFPA sections without eight full forms. AI systems replace human test takers only where explicitly reinterpreted; human demographic norms, disability accommodations and personal debriefing are inapplicable to these probes. Unreported methods remain unknown, not automatically inapplicable. Probe labels are not EFPA ratings; no aggregate quality score was calculated."
}
